pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: item placed leaves exactly enough for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits in the post-residual but with slack: partial reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0 + 0.3 * (post_residual - next_item_size) as f64;
    }
    // Next item cannot fit here: penalize proportionally to wasted potential.
    if next_item_size > post_residual {
        score += 10.0 + 0.2 * (next_item_size - post_residual) as f64;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Penalize small dead space (unusable residuals) relative to mean residual.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward leaving residuals that are close to the mean (keeps bins balanced).
    score += 0.25 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate: only attractive when residuals are tight or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = mean_residual < item_size as f64;
        if tight && fitting_bins_count > 1 {
            score += 40.0; // keep using open bins when they fit
        } else {
            score += 5.0 + 30.0 * progress; // mild preference early, discourage late
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: keep parent's polynomial coupling of post_residual with progress
    let poly = norm_pr * (1.0 + 0.8 * progress) * (1.0 - 0.5 * norm_pr * progress);
    let mut score = poly * cap;

    // Dead-space penalty as stream progresses
    score += 0.35 * progress * norm_pr * norm_pr * cap;

    // Exact-fill reward: leaving nothing behind is ideal (borrowed from best heuristic)
    if post_residual == 0 {
        score -= 800.0;
    } else if post_residual < 5 {
        score -= 200.0;
    } else if post_residual < 10 {
        score += 40.0; // unusable sliver
    }

    // Decade-harmonic bonus: residuals that are multiples of 10 pair with clustered sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 30.0;
    }

    // Lookahead: reward leaving room for the next item, with snugness scaling
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let snug = 1.0 - (pr - nxt) / 50.0;
            score -= (6.0 * (1.0 - progress) + 120.0 * snug.max(0.0)) * ((pr - nxt) / cap + 0.01);
            if next_item_size as u32 == post_residual {
                score -= 400.0; // perfect chain
            }
            if post_residual / 10 + next_item_size / 10 == bin_capacity / 10 {
                score -= 150.0; // perfect complement to capacity
            }
        } else {
            score += 4.0 * ((nxt - pr) / cap) + 0.3 * pr.min(80.0);
        }
    } else {
        // Last item: minimize waste aggressively
        score += 5.0 * pr;
    }

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Preference for tighter bins overall
    score += 0.1 * (mean_residual - pr) / cap + 0.2 * (bin_residual - item_size) as f64;

    // Consolidation: bins below mean residual are almost full, prefer them
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    }

    // New-bin candidate: only attractive for large items or when open fits are poor
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        let mut open_cost = 60.0 + 80.0 * progress;
        if item_size as f64 > mean_residual {
            open_cost -= 120.0;
        }
        open_cost += 12.0 * (1.0 - fill) * (1.0 - 0.3 * progress);
        score += open_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Post-residuals in the "unusable gap" zone (1..=12) are heavily penalized:
    // space too small for typical items is wasted forever.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 * (1.0 + (12 - post_residual) as f64 / 12.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    } else if post_residual >= 20 && post_residual <= 60 {
        // Mid-range residual is still useful for future items; mild reward.
        score -= 6.0;
    }

    // --- Tightness reward: fraction of the bin consumed by this placement ---
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // --- Open-bin pressure: mildly discourage spreading across many bins ---
    score += 0.6 * open_bins_count as f64;

    // --- Last-chance bin: if this is the only bin that fits, avoid forcing a new bin
    // unless the fit is truly terrible (dead-space penalty above already dominates).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // --- Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits: mildly reward leaving compatible space.
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
        // Dead space that the next item cannot use: extra penalty.
        score += 20.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is justified only if no open bin fits well,
        // or if all open bins would leave unusable dead space.
        let poor_fits = fitting_bins_count == 0
            || (fitting_bins_count <= 2 && mean_residual < item_size as f64 * 0.6);
        if poor_fits {
            score -= 45.0; // prefer opening a fresh bin
        } else {
            score += 35.0; // good fits exist elsewhere; don't waste a fresh bin
        }
    }

    // --- Stream progression: late in the stream, be more conservative with new bins
    // and more aggressive about closing out bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - fill_ratio);

    // --- Mean-residual coupling: bins far below mean residual are less attractive
    // (their space is more valuable to keep for other items).
    if bin_residual != bin_capacity {
        let dev = mean_residual - post_residual as f64;
        score += 0.15 * dev.max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer low post-residual, with non-linear (quadratic) sharpening.
    let mut score = pr * (1.0 + 0.8 * pr_norm);

    // Stream-progress coupling: as stream advances, tolerate residual less (tight packing matters more).
    let progress_pressure = 1.0 + 1.5 * progress * (1.0 - progress) * 4.0; // peaks mid-stream
    score *= progress_pressure;

    // Cubic residual penalty grows with progress: dead space is costlier later.
    score += pr_norm.powi(3) * cap * progress * 10.0;

    // Perfect fit reward (smooth via gaussian-like term).
    let perfect = ((pr_norm * 20.0).powi(2)).exp() - 1.0;
    score -= perfect * 5.0;

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    }

    // Lookahead: if next item fits snugly in post-residual, reward this placement.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let snug = (-gap / 12.0).exp();
        score -= snug * 6.0 * (1.0 + progress);
        // Penalize leaving residual that neither fits next item well nor is small.
        if post_residual < next_item_size {
            score += 4.0 * (1.0 - progress);
        }
    }

    // Slight preference to use bins when many are open (consolidation).
    score += open_bins_count as f64 * 0.15;

    // Penalize bins far below mean residual (fragmentation smoothing).
    score += 0.5 * (mean_residual - pr).abs();

    // New-bin candidate: baseline cost so it's only chosen when clearly better.
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - progress) + mean_residual * 0.05;
    }

    score
}

