pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: tight fits preferred (low post residual).
    let mut score = pr;

    // Non-linear waste penalty: quadratic in normalized residual, growing with stream progress.
    score += norm_pr * norm_pr * cap * (0.5 + progress);

    // Smoothly reward using existing bins vs opening a new one.
    let is_new_bin = if bin_residual == bin_capacity { 1.0 } else { 0.0 };
    score += is_new_bin * (cap * (0.35 + 0.3 * progress));

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    let last_chance = if fitting_bins_count == 1 && is_new_bin == 0.0 { 1.0 } else { 0.0 };
    score -= last_chance * cap * (0.4 + 0.4 * progress);

    // Reward bins whose residual is below mean (denser bins), smooth coupling.
    score += (mean_residual - bin_residual as f64) * 0.3 * (1.0 - is_new_bin);

    // Lookahead: penalize leaving residual that neither fits the next item nor is tiny.
    if next_item_size > 0 && is_new_bin == 0.0 {
        let gap = next_item_size as f64 - pr;
        if gap > 0.0 {
            score += gap * 0.25;
        } else {
            score += (pr - next_item_size as f64) * 0.1;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into coarse buckets.
    // Perfect fit (post_residual == 0) is best; tiny leftovers (1..=10) are dead space.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit: strongly reward
    } else {
        let class = match post_residual {
            1..=10 => 0,      // near-dead space
            11..=20 => 1,
            21..=30 => 2,
            31..=50 => 3,
            51..=70 => 4,
            _ => 5,           // large leftover, still reusable
        };
        // Penalize small leftovers quadratically within the class
        score += (class as f64) * -15.0 + (10 - post_residual.min(10)) as f64 * 3.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 60.0 - slack * 0.5;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use this leftover; penalize proportional to leftover size
        score += post_residual as f64 * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin, discounted when many bins already open
        score += 150.0 - (open_bins_count as f64).min(50.0);
        // but if post_residual (== capacity) leaves room for next item too, fine
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 40.0;
        }
    }

    // Prefer filling bins that are already relatively full (low residual before placement)
    score += (bin_residual as f64 / bin_capacity as f64) * -20.0;

    // Mild time decay: later in the stream, be more greedy about perfect fits
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 10.0 * (post_residual == 0) as i32 as f64;

    // Deviation from mean residual: prefer bins below mean residual (fuller bins)
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps are nearly useless -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 4.0; // gap 1 => +56, gap 9 => +24
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 50.0;
    }

    // Reward placements that leave room for the lookahead item (k=2).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Residual too small for the next item: dead space confirmed.
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open-bin pressure is high
    // or mean residual is already too small to matter.
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64;
        if mean_residual < item_size as f64 {
            score -= 25.0;
        }
        // Late in the stream, avoid spawning bins with huge leftover waste.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 * (1.0 - progress) * (post_residual as f64) / bin_capacity as f64;
    }

    // Mild penalty for spreading residual unevenly vs the mean.
    score += 0.05 * ((post_residual as f64) - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: this placement leaves exactly the space the next item needs.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Good: next item fits in the leftover space.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward for a snug fit (little slack beyond the next item).
        let slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - slack / bin_capacity as f64);
    }
    // Penalize leftover that the next item cannot use (dead space risk).
    else if next_item_size > 0 {
        let gap = (next_item_size - post_residual) as f64;
        score += 0.35 * gap;
    }

    // Reward tight packing now: small post_residual is valuable.
    score -= 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize bins already below mean residual (keep big bins flexible),
    // reward bins above mean residual (use up loose space).
    score += 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive early in the stream or when it fits
    // the next item perfectly; otherwise make it unattractive.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 + 40.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // Slight preference for consolidating when many bins are open.
    score += 1.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (low post_residual), scaled non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Strong reward for near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose residual after placement can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.25 * next_item_size as f64;
    }
    // Penalize creating residual that is a dead zone (too small for typical items)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Global pressure: when many open bins exist, prefer filling existing ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= 3.0 * pressure;
    } else {
        // New-bin candidate: only attractive when few bins fit or residuals are bloated.
        score += 20.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 100.0;
        } else if fitting_bins_count == 1 {
            // discourage abandoning the sole fitting bin
            score += 35.0;
        }
        // Prefer new bin if mean residual across open bins is high (fragmented state).
        score += 0.3 * (mean_residual - 25.0).max(0.0);
    }

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, with non-linear (quadratic) waste growth
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth coupling of residual waste with stream progress:
    // early on, waste matters less (bins will be reused); late, compact tightly
    let progress_weight = 0.5 + 2.5 * progress * progress;
    score *= progress_weight;

    // Reward tight fits via a smooth saturating term of fill ratio
    let fill = 1.0 - norm_pr;
    score -= 30.0 * fill * fill * fill;

    // Penalize when post_residual can't fit the next item (smooth hinge via tanh-like poly)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr) / cap;
        if gap > 0.0 {
            let g = gap / (1.0 + gap);
            score += 25.0 * g * g * (open_bins_count as f64).sqrt();
        } else {
            // next item fits: reward proportional to how well it fills
            score -= 10.0 * (-gap * cap / 50.0).min(1.0);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Mild penalty for spreading across many bins when mean residual is high
    score += 0.05 * (mean_residual - pr).abs() * (1.0 + progress);

    // New-bin candidate calibration: empty bin gets a moderate default cost
    if bin_residual == bin_capacity {
        score = 55.0 + 30.0 * progress - 5.0 * (item_size as f64 / cap);
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of the post residual: which "companion sizes" fit?
    // Class 0: post_residual == 0 -> perfect fit, reward strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Integer-division thresholds on post_residual (harmonic classes of cap/8)
        let eighth = bin_capacity / 8;   // 12
        let quarter = bin_capacity / 4;  // 25
        let half = bin_capacity / 2;     // 50
        if post_residual <= eighth {
            score -= 25.0; // near-perfect sliver, fine
        } else if post_residual <= quarter {
            score -= 10.0; // usable small class
        } else if post_residual <= half {
            score += 8.0; // mid dead-zone: wastes space
        } else {
            score -= 5.0; // large residual, still flexible
        }

        // Modulo coupling: does post_residual align with common item classes?
        // Items 1..100; reward residuals that are multiples of small harmonic units
        if post_residual % 10 == 0 {
            score -= 6.0;
        }
        if post_residual % 25 == 0 {
            score -= 4.0;
        }

        // Lookahead: penalize if next item cannot use this residual
        if next_item_size > 0 {
            if next_item_size > post_residual {
                score += 12.0; // dead space for the next item
            } else {
                // exact harmonic match reward
                if post_residual == next_item_size {
                    score -= 30.0;
                } else if post_residual - next_item_size <= eighth {
                    score -= 18.0; // next item nearly fills bin
                } else {
                    score -= 6.0;
                }
            }
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make it moderately attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = mean_residual / cap;
        score = 15.0 + 40.0 * (1.0 - crowding) * (1.0 - 0.3 * progress);
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    }

    // Slight penalty for bin sprawl: prefer filling existing bins early
    score += (open_bins_count as f64).sqrt() * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Strict dead-space avoidance ---
    // Post-residuals in the "unusable gap" zone (1..=12) are heavily penalized:
    // space too small for typical items is wasted forever.
    if post_residual > 0 && post_residual <= 12 {
        score += 60.0 * (1.0 + (12 - post_residual) as f64 / 12.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 80.0;
    } else if post_residual >= 20 && post_residual <= 60 {
        // Mid-range residual is still useful for future items; mild reward.
        score -= 6.0;
    }

    // --- Tightness reward: fraction of the bin consumed by this placement ---
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // --- Open-bin pressure: mildly discourage spreading across many bins ---
    score += 0.6 * open_bins_count as f64;

    // --- Last-chance bin: if this is the only bin that fits, avoid forcing a new bin
    // unless the fit is truly terrible (dead-space penalty above already dominates).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // --- Lookahead: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 50.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits: mildly reward leaving compatible space.
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
        // Dead space that the next item cannot use: extra penalty.
        score += 20.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is justified only if no open bin fits well,
        // or if all open bins would leave unusable dead space.
        let poor_fits = fitting_bins_count == 0
            || (fitting_bins_count <= 2 && mean_residual < item_size as f64 * 0.6);
        if poor_fits {
            score -= 45.0; // prefer opening a fresh bin
        } else {
            score += 35.0; // good fits exist elsewhere; don't waste a fresh bin
        }
    }

    // --- Stream progression: late in the stream, be more conservative with new bins
    // and more aggressive about closing out bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - fill_ratio);

    // --- Mean-residual coupling: bins far below mean residual are less attractive
    // (their space is more valuable to keep for other items).
    if bin_residual != bin_capacity {
        let dev = mean_residual - post_residual as f64;
        score += 0.15 * dev.max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = 0.0;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit: penalize wasted residual relative to item size
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Lookahead: bonus if next item fits into the post-residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0 + 0.5 * next_item_size as f64;
        } else {
            // post-residual too small for next item: penalize dead space
            score += 0.3 * post_residual as f64 * (1.0 - t);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Few fitting bins: mild favor to consolidate
    if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0).log2();
    }

    // Prefer bins with residual close to item size (best-fit style)
    score += (bin_residual as f64 - item_size as f64).abs() * 0.4;

    // Global state: if mean residual is high, encourage filling existing bins
    score -= 0.2 * mean_residual * t;

    // New-bin candidate handling: empty bin gets a moderate penalty so it's
    // chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        let urgency = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 60.0 - 60.0 * urgency + 10.0 * (1.0 - t);
    }

    // Prefer bins with larger residual when many bins open (consolidation)
    score -= 0.1 * bin_residual as f64 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: quadratic dead-space penalty with smooth progress scaling.
    let mut score = pr * (1.0 + 1.5 * pr_norm * (0.5 + progress));

    // Smooth non-linear interaction: residual tightness vs stream progress.
    let tightness = 1.0 - pr_norm;
    score -= 8.0 * tightness.powf(2.0) * (0.5 + progress);

    // Lookahead coupling: reward residuals that leave room for the next item
    // (smoothly weighted by progress), penalize near-misses.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr >= nxt) as i32 as f64;
        let gap = (pr - nxt).abs() / cap;
        score -= 6.0 * fits_next * (1.0 - gap) * (0.3 + 0.7 * progress);
        score += 4.0 * (1.0 - fits_next) * (1.0 - gap) * (0.3 + 0.7 * progress);
    }

    // Last-chance bonus: strongly favor using the only fitting bin,
    // scaled smoothly by progress.
    if fitting_bins_count == 1 {
        score -= 10.0 * (0.4 + 0.6 * progress);
    }

    // Mild pressure against accumulating many loose bins late in the stream.
    score += 0.5 * (open_bins_count as f64).powf(1.2) * progress * pr_norm;

    // Deviation from mean residual: prefer bins near the mean (smooth balance).
    score += 0.3 * (pr - mean_residual).abs() * (0.5 + progress);

    // New-bin candidate: make it progressively less attractive, but allow
    // early in stream or when residual is tiny.
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * progress - 3.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which "slot class" does the leftover fall into?
    // Classes based on integer division by 10 (deciles of capacity).
    let post_class = post_residual / 10;
    let item_class = item_size / 10;

    // Reward exact or near-exact fills: post_residual in {0} is perfect, tiny leftovers are dead space.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 5 {
        score -= 300.0;
    } else if post_residual < 10 {
        score += 50.0; // unusable sliver: dead space penalty
    }

    // Modulo-10 harmonic bonus: leftovers that are multiples of 10 pair well with
    // common item sizes (sizes tend to cluster on decade boundaries).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 40.0;
    }

    // Class-compatibility: does the next item fit into the post_residual class?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect chain
        } else if next_item_size <= post_residual {
            // scaled by how snugly next item nests in the leftover
            let snug = 1.0 - (post_residual - next_item_size) as f64 / 50.0;
            score -= 120.0 * snug;
        } else {
            // next item cannot use this leftover: penalize large stranded residuals
            score += 0.3 * (post_residual as f64).min(80.0);
        }
        // Harmonic pairing: leftover class + next item class summing to capacity/10 (perfect complement)
        if post_class + next_item_size / 10 == bin_capacity / 10 {
            score -= 200.0;
        }
    } else {
        // Last item: minimize waste aggressively.
        score += 5.0 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate handling: empty bin should only win when current fit is bad.
    if bin_residual == bin_capacity {
        // mild default preference for existing bins: add a small opening cost
        score += 60.0;
        // but if the item is huge relative to mean residual, opening fresh is fine
        if item_size as f64 > mean_residual {
            score -= 150.0;
        }
        // late in the stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 * progress;
    }

    // Prefer tighter bins: residual before placement closer to item size is better.
    score += 0.2 * (bin_residual - item_size) as f64;

    // Coupling with mean residual: bins far below mean residual are "almost full",
    // using them consolidates space.
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    }

    // Large items should go into large-residual bins (harmonic size matching).
    let residual_quarter = bin_residual / (bin_capacity / 4).max(1);
    let item_quarter = item_size / (bin_capacity / 4).max(1);
    if residual_quarter >= item_quarter {
        score -= 30.0 * item_quarter as f64;
    } else {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to fit even the
    // smallest plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Small unusable-ish gaps: moderate penalty scaled by how dead the gap is.
        score += (20.0 - post_residual as f64) * 3.0;
    }

    // Reward tight fits (post_residual close to 0 but still usable).
    if post_residual > 0 {
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= 15.0 * tightness * tightness;
    } else {
        // Perfect fill: strong reward.
        score -= 40.0;
    }

    // If this bin is the last chance to avoid opening a new bin, favor using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, prefer filling existing ones
    // over spreading; when few bins are open, allow opening new bins more freely.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open-bin count is high, reward early.
        score += 20.0 + 8.0 * pressure;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
    } else {
        // Existing bin: discount slightly as open-bin pressure grows.
        score -= 2.0 * pressure;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slightly penalize leaving awkward gaps.
        if post_residual > 0 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (concentrate filling into already-partial bins).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Late in the stream, close out bins aggressively (avoid stragglers).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && post_residual > 0 {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step chain: item placed leaves exactly enough for the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits in the post-residual but with slack: partial reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0 + 0.3 * (post_residual - next_item_size) as f64;
    }
    // Next item cannot fit here: penalize proportionally to wasted potential.
    if next_item_size > post_residual {
        score += 10.0 + 0.2 * (next_item_size - post_residual) as f64;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Penalize small dead space (unusable residuals) relative to mean residual.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Reward leaving residuals that are close to the mean (keeps bins balanced).
    score += 0.25 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate: only attractive when residuals are tight or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let tight = mean_residual < item_size as f64;
        if tight && fitting_bins_count > 1 {
            score += 40.0; // keep using open bins when they fit
        } else {
            score += 5.0 + 30.0 * progress; // mild preference early, discourage late
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small dead space).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: reward if next item fits the post-residual (chaining).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Penalize leaving a gap slightly too small for the next item.
            let waste = post_residual as f64 - (next_item_size as f64 * 0.5);
            if waste > 0.0 {
                score += 0.35 * waste;
            }
        }
    }

    // Penalize bins whose residual deviates far below the mean (fragmentation).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Mild penalty for spreading across many open bins; encourage consolidation.
    score += 0.6 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no good existing option or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let item_is_big = item_size as f64 / bin_capacity as f64;
        score += 55.0 - 40.0 * item_is_big + 20.0 * (1.0 - progress);
        if fitting_bins_count <= 1 {
            score -= 60.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Time-horizon: late in the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 25.0 * progress;
    } else {
        score -= 8.0 * progress;
    }

    score
