pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never accept the
    // smallest possible item (1..10) are pure waste -> heavy penalty.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward bins whose residual tightly matches the item (tight fit).
    let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score -= 25.0 * (1.0 - tightness);

    // Pressure term: with many open bins, discourage spreading; prefer
    // filling existing bins rather than fragmenting.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when the item barely fits any
    // open bin or open-bin set is tiny; otherwise penalize opening bins.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (mean_residual / bin_capacity as f64 + 1.0);
        score += 15.0 + 5.0 * pressure;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // new bin can also host the lookahead item
        }
    }

    // Lookahead coupling: if the next item fits the post-residual exactly
    // or well, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 20.0; // chain fit: near-perfect two-item packing
        }
    }

    // Mild stream-progression regularization: late in the stream, be more
    // tolerant of imperfect fits to avoid excessive new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

