        if (pr - next).abs() < 1.0 {
            score -= 500.0;
        } else if next <= pr {
            // next item fits: reward proportionally to tightness
            let tight = 1.0 - (pr - next) / pr.max(1.0);
            score -= 200.0 * tight;
        } else {
            // next item cannot fit in the leftover: penalize dead space
            let waste = (next - pr).min(pr);
            score += 0.5 * waste;
