    score -= 12.0 * tightness * tightness;

    // Penalize leaving awkward dead space: residual that is too small to be useful.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Lookahead coupling: prefer bins whose post_residual can host the next item.
    if next_item_size > 0 {
