        } else {
            score += 3.0 * (next_item_size as f64 - post_residual as f64) / cap;
        }
    }

    // Time horizon: early in the stream, be more willing to open new bins (explore);
    // later, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening bins, more so late in the stream.
        score += 4.0 + 20.0 * progress;
        // But allow opening when existing bins are very full on average.
        score -= 6.0 * (mean_residual / cap).max(0.0).min(1.0);
        // Few open bins relative to stream: allow exploration.
        if open_bins_count < 4 { score -= 3.0; }
    } else {
        // Favor bins below mean residual (fill emptier bins first) early,
        // but prefer best-fit behavior late.
        score += (1.0 - progress) * ((bin_residual as f64 - mean_residual) / cap) * 4.0;
    }

    // Mild penalty for spreading across many bins.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
