        5 => score += 2.0,            // half-full: mediocre
        6 => score += 5.0,
        7 => score += 9.0,
        8 => score += 14.0,
        9 => score += 20.0,
        _ => {}                        // empty/new bin class handled below
    }

    // Modulo-10 fine tuning: residuals divisible by 10 are more reusable
    if pr % 10 == 0 && pr > 0 {
        score -= 6.0;
    }

    // Dead-space penalty: residual too small for any plausible item (min size 1..100)
    if pr > 0 && pr < 10 {
        score += 30.0;
    }

    // Lookahead coupling: reward if next item fits the post residual exactly or well
    if next_item_size > 0 {
        if next_item_size == pr {
