        if open_bins_count == 0 {
            score -= 200.0; // must open first bin
        }
        // late in the stream, avoid spreading out
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
    }

    // Prefer bins tighter than the mean residual (better packing direction)
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Small tie-break noise-free determinism: favor earlier (tighter) bins via residual
    score += 0.01 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
