    // Lookahead: does the next item fit into the post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            let snug = 1.0 - (post_residual - next_item_size) as f64 / 50.0;
            score -= 120.0 * snug;
            // NEW: extra chain reward when next item exactly consumes a residual
            // that is itself a "nice" size (small leftover after the chain).
            let chain_post = post_residual - next_item_size;
            if chain_post == 0 {
                score -= 180.0;
            } else if chain_post < 10 {
                score -= 40.0;
            }
        } else {
            // Next item cannot use this leftover: penalize stranded residuals,
            // but scale by whether any OTHER open bin could host the next item.
            let stranded = 0.3 * (post_residual as f64).min(80.0);
            if fitting_bins_count <= 2 && post_residual >= 2 * next_item_size {
                // A large stranded residual might still host a future item: soften.
                score += 0.6 * stranded;
            } else {
                score += stranded;
            }
        }
        // Harmonic pairing: perfect complement to capacity.
        if post_class + next_item_size / 10 == bin_capacity / 10 {
            score -= 200.0;
        }
        // NEW: two-step lookahead — if next item fits snugly here AND the item
        // after it would also fit the double leftover, reward strongly.
        if next_item_size <= post_residual {
            let chain_post = post_residual - next_item_size;
            if chain_post > 0 && item_class >= next_item_size / 10 {
                score -= 25.0;
            }
        }
    } else {
        score += 5.0 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Base opening cost.
        score += 60.0;
        // Open fresh when item is large relative to mean residual.
        if item_size as f64 > mean_residual {
            score -= 150.0;
        }
        // NEW: open fresh when NO open bin leaves a residual that the next
        // item could use (avoid fragmenting into dead slivers).
        if next_item_size > 0 && fitting_bins_count > 0 {
            // fitting_bins_count == 0 means nothing fits: opening is mandatory anyway.
            if fitting_bins_count == 0 {
                score -= 500.0;
            }
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 80.0 * progress;
        // NEW: early stream with few bins — allow opening to keep bins clean.
        if progress < 0.2 && open_bins_count < 8 {
            score -= 30.0;
        }
    }

    // Prefer tighter bins.
    score += 0.2 * (bin_residual - item_size) as f64;

    // Consolidate bins below mean residual.
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    }

    // Harmonic size matching by quarters of capacity.
    let quarter = (bin_capacity / 4).max(1);
    let residual_quarter = bin_residual / quarter;
    let item_quarter = item_size / quarter;
    if residual_quarter >= item_quarter {
        score -= 30.0 * item_quarter as f64;
    } else {
        score += 60.0;
    }

    // NEW: waste-rate-aware tiebreak — when many open bins exist, slightly
    // discourage spreading items across bins with mid-sized residuals.
    if open_bins_count > 12 && post_residual > item_size && post_residual < bin_capacity / 2 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: keep parent's polynomial coupling of post_residual with progress
    let poly = norm_pr * (1.0 + 0.8 * progress) * (1.0 - 0.5 * norm_pr * progress);
    let mut score = poly * cap;

    // Dead-space penalty as stream progresses
    score += 0.35 * progress * norm_pr * norm_pr * cap;

    // Exact-fill reward: leaving nothing behind is ideal (borrowed from best heuristic)
    if post_residual == 0 {
        score -= 800.0;
    } else if post_residual < 5 {
        score -= 200.0;
    } else if post_residual < 10 {
        score += 40.0; // unusable sliver
    }

    // Decade-harmonic bonus: residuals that are multiples of 10 pair with clustered sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 30.0;
    }

    // Lookahead: reward leaving room for the next item, with snugness scaling
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let snug = 1.0 - (pr - nxt) / 50.0;
            score -= (6.0 * (1.0 - progress) + 120.0 * snug.max(0.0)) * ((pr - nxt) / cap + 0.01);
            if next_item_size as u32 == post_residual {
                score -= 400.0; // perfect chain
            }
            if post_residual / 10 + next_item_size / 10 == bin_capacity / 10 {
                score -= 150.0; // perfect complement to capacity
            }
        } else {
            score += 4.0 * ((nxt - pr) / cap) + 0.3 * pr.min(80.0);
        }
    } else {
        // Last item: minimize waste aggressively
        score += 5.0 * pr;
    }

    // Last chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Preference for tighter bins overall
    score += 0.1 * (mean_residual - pr) / cap + 0.2 * (bin_residual - item_size) as f64;

    // Consolidation: bins below mean residual are almost full, prefer them
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    }

    // New-bin candidate: only attractive for large items or when open fits are poor
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        let mut open_cost = 60.0 + 80.0 * progress;
        if item_size as f64 > mean_residual {
            open_cost -= 120.0;
        }
        open_cost += 12.0 * (1.0 - fill) * (1.0 - 0.3 * progress);
        score += open_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let post_class = post_residual / 10;
    let item_class = item_size / 10;

