        score -= 1200.0;
    } else if post_residual < 5 {
        score -= 300.0;
    } else if post_residual < 10 {
        score += 50.0;
    }

    // Decade-harmonic leftovers pair well with clustered sizes
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 40.0;
    }

    // Two-step lookahead: how much of the leftover can the NEXT TWO items consume?
    let lookahead = next_item_size as u64 + if step_index + 2 < total_items { 0 } else { 0 };
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 550.0;
        } else if next_item_size <= post_residual {
            let snug = 1.0 - (post_residual - next_item_size) as f64 / 50.0;
            score -= 120.0 * snug;
        } else {
            // stranded leftover: penalize proportionally, capped
            score += 0.3 * (post_residual as f64).min(80.0);
        }
        if post_class + next_item_size / 10 == bin_capacity / 10 {
            score -= 200.0;
        }
        // NEW: if next item cannot fit post_residual but would fit the pre-residual
        // alongside the current item, prefer this bin (sequential packing).
        if next_item_size > post_residual && next_item_size <= bin_residual {
            score -= 45.0;
        }
    } else {
        score += 5.0 * post_residual as f64;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // opening cost grows with how well the item could nest elsewhere
        let mut open_cost = 60.0 + 80.0 * progress;
        if item_size as f64 > mean_residual * 1.15 {
            open_cost -= 150.0;
        }
        // huge items near capacity: opening fresh is fine
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            open_cost -= 60.0;
        }
        // small items late in stream: strongly consolidate
        if item_size <= 10 && progress > 0.5 {
            open_cost += 120.0;
        }
        score += open_cost;
    }

    // Tighter bins preferred
    score += 0.2 * (bin_residual - item_size) as f64;

    // Below-mean-residual bins are almost full: consolidate
    if (bin_residual as f64) < mean_residual {
        score -= 15.0;
    }

    // Quarter-harmonic matching
    let quarter = (bin_capacity / 4).max(1);
    let residual_quarter = bin_residual / quarter;
    let item_quarter = item_size / quarter;
    if residual_quarter >= item_quarter {
        score -= 30.0 * item_quarter as f64;
    } else {
        score += 60.0;
    }

    // NEW: waste-rate coupling — with many open bins, squeeze harder into existing ones
    if open_bins_count > 8 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    score
}

