pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Exact / near-exact fills: heavy rewards ---
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 5 {
        score -= 300.0;
    } else if post_residual <= 12 {
        // Dead-space zone: too small for typical items
        score += 60.0 * (1.0 + (12 - post_residual) as f64 / 12.0);
    } else if post_residual % 10 == 0 {
        // Decade-aligned leftovers pair well with common sizes
        score -= 40.0;
    } else if post_residual <= 60 {
        score -= 6.0;
    }

    // --- Tightness reward ---
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fill_ratio * fill_ratio;

    // Prefer tighter bins: leftover space before placement close to item size
    score += 0.2 * (bin_residual.saturating_sub(item_size)) as f64;

    // --- Last-chance bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // --- Lookahead with the next item ---
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0; // perfect chain
        } else if next_item_size <= post_residual {
            let snug = 1.0 - (post_residual - next_item_size) as f64 / 50.0;
            score -= 120.0 * snug;
        } else if post_residual < 15 {
            // Dead space the next item cannot use
            score += 20.0 + 0.3 * (post_residual as f64).min(80.0);
        }
        // Harmonic complement: leftover + next item fills the bin exactly
        if post_residual + next_item_size == bin_residual {
            score -= 200.0;
        }
    } else if next_item_size == 0 {
        // Last item: minimize waste aggressively
        score += 5.0 * post_residual as f64;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        let poor_fits = fitting_bins_count == 0
            || (fitting_bins_count <= 2 && mean_residual < item_size as f64 * 0.6)
            || item_size as f64 > mean_residual;
        let progress = step_index as f64 / total_items.max(1) as f64;
        if poor_fits {
            score -= 45.0 - 60.0 * progress; // late in stream, less eager to open
        } else {
            score += 60.0 + 40.0 * progress;
        }
    }

    // --- Open-bin pressure ---
    score += 0.6 * open_bins_count as f64;

    // --- Mean-residual coupling ---
    if bin_residual != bin_capacity {
        let dev = mean_residual - post_residual as f64;
        score += 0.15 * dev.max(0.0);
        if (bin_residual as f64) < mean_residual {
            score -= 15.0;
        }
    }

    // --- Late-stream consolidation ---
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - fill_ratio);

    score
}
